 "content": "def transform(grid):
    """Recolor alternating 2x2 objects, counting from the rightmost object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    rr, cc = stack.pop()
                    cells.append((rr, cc))
                    for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
                objects.append(cells)
    objects.sort(key=lambda cells: (min(c for r, c in cells), min(r for r, c in cells)))
    # Starting at the rightmost object, color every other object with 8.
    for rank_from_right, cells in enumerate(reversed(objects)):
        if rank_from_right % 2 == 0:
            for r, c in cells:
                out[r][c] = 8
    return out

